import pathlib,json,hashlib
root=pathlib.Path(__file__).resolve().parents[2];src=root/'source';out=root/'audit';rows=[]
def add(rel,claim,ranges,missing):
 file='packages/ui/src/'+rel;lines=(src/file).read_text().splitlines();ev=[]
 for a,b in ranges:
  assert 1<=a<=b<=len(lines)
  ev.append({'file':file,'startLine':a,'endLine':b,'excerpt':'\n'.join(lines[a-1:b]),'sha256':hashlib.sha256((src/file).read_bytes()).hexdigest()})
 rows.append({'id':f'WEB-VIS-{len(rows)+1:02d}','file':file,'claim':claim,'scope':'Named control-flow, component branches and markup only; no inherited child/callback certification','auditDepth':'EXACT_SURFACE_FRAGMENT_SOURCE_REVIEW','status':'PARTIAL','evidence':ev,'missingProof':missing,'runtimeStatus':'NOT EXECUTED','testStatus':'No new tests or browser/WebGL probes'})
